messages.content:
{
  "title": "functions.expression.BooleanInputSchema",
  "description": "Schema for a boolean input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the boolean.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.BooleanInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.SimpleContentExpression",
  "description": "Expression variant of [`SimpleContent`] for dynamic content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part text content expressions.",
      "type": "array",
      "items": {
        "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
        "anyOf": [
          {
            "title": "Expression",
            "description": "An expression (JMESPath or Starlark) to evaluate.",
            "$ref": "functions.expression.Expression"
          },
          {
            "title": "Value",
            "description": "A literal value.",
            "$ref": "agent.completions.message.SimpleContentPartExpression"
          }
        ]
      }
    }
  ]
}

{
  "title": "agent.completions.message.VideoUrl",
  "description": "A video URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the video.",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.UserMessageExpression",
  "description": "Expression variant of [`UserMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.\n\nA value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "$ref": "agent.completions.message.RichContentExpression"
        }
      ]
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
          "anyOf": [
            {
              "title": "Expression",
              "description": "An expression (JMESPath or Starlark) to evaluate.",
              "$ref": "functions.expression.Expression"
            },
            {
              "title": "Value",
              "description": "A literal value.",
              "type": "string"
            }
          ]
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}
